			if (prediction.evidenceSource() != LmdbNativeCostPrediction.EvidenceSource.EXACT_VARIANT
					|| prediction.nEff() < config.guardMinBackupEvidence() || prediction.quarantined()
					|| !prediction.uniformlyPriceable()) {
				continue;
			}
